/** Units of time. */
export type TimeUnitType =
  | 'ns'
  | 'µs'
  | 'ms'
  | 's'
  | 'min'
  | 'h'
  | 'd'
  | 'mo'
  | 'y';

/** Units of data in bits */
export type DataUnitBitType =
  | 'bit'
  | 'kbit'
  | 'Mbit'
  | 'Gbit'
  | 'Tbit'
  | 'Pbit';

/** Units of data in bytes */
export type DataUnitByteType = 'byte' | 'kB' | 'MB' | 'GB' | 'TB' | 'PB';

/** Units of data. */
export type DataUnitType = DataUnitBitType & DataUnitByteType;

/** Units of exponential numbers, i.e. kilo, million, ect. */
export type ExponentialNumberUnitType = 'K' | 'M' | 'B' | 'T';

//#region Time conversion factorial helpers
const nanosecond = 1;
const microsecond = nanosecond * 1000;
const millisecond = microsecond * 1000;
const second = millisecond * 1000;
const minute = second * 60;
const hour = minute * 60;
const day = hour * 24;
// This number is the average between 30 day months, 31 day months and february's rebellious 28 and 29 day nature.
const month = day * 30.41666;
const year = month * 12;
//#endregion

/** Conversion factors for all time units to nanosecond */
export const TimeConversionFactors: Array<{
  multiplier: number;
  postfix: TimeUnitType;
}> = [
  { multiplier: year, postfix: 'y' },
  { multiplier: month, postfix: 'mo' },
  { multiplier: day, postfix: 'd' },
  { multiplier: hour, postfix: 'h' },
  { multiplier: minute, postfix: 'min' },
  { multiplier: second, postfix: 's' },
  { multiplier: millisecond, postfix: 'ms' },
  { multiplier: microsecond, postfix: 'µs' },
  { multiplier: nanosecond, postfix: 'ns' },
];

/**
 * Levels of abbreviations for decimal exponents from kilo to trillion,
 * 10^3, 10^6, ...
 */
export const ExponentialDecimalLevels: Array<{
  multiplier: number;
  postfix: ExponentialNumberUnitType;
}> = [
  { multiplier: Math.pow(10, 12), postfix: 'T' },
  { multiplier: Math.pow(10, 9), postfix: 'B' },
  { multiplier: Math.pow(10, 6), postfix: 'M' },
  { multiplier: Math.pow(10, 3), postfix: 'K' },
];

/**
 * Levels of abbreviation for octal bit exponents from kilobit to petabits,
 * 2^10, 2^20, 2^30...
 */
export const ExponentialOctalBitLevels: Array<{
  multiplier: number;
  postfix: DataUnitBitType;
}> = [
  { multiplier: Math.pow(2, 50), postfix: 'Pbit' },
  { multiplier: Math.pow(2, 40), postfix: 'Tbit' },
  { multiplier: Math.pow(2, 30), postfix: 'Gbit' },
  { multiplier: Math.pow(2, 20), postfix: 'Mbit' },
  { multiplier: Math.pow(2, 10), postfix: 'kbit' },
];

/**
 * Levels of abbreviation for octal byte exponents from kilobyte to petabyte,
 * 2^10, 2^20, 2^30...
 */
export const ExponentialOctalByteLevels: Array<{
  multiplier: number;
  postfix: DataUnitByteType;
}> = [
  { multiplier: Math.pow(2, 50), postfix: 'PB' },
  { multiplier: Math.pow(2, 40), postfix: 'TB' },
  { multiplier: Math.pow(2, 30), postfix: 'GB' },
  { multiplier: Math.pow(2, 20), postfix: 'MB' },
  { multiplier: Math.pow(2, 10), postfix: 'kB' },
];
